,directives:[]}]}}]}}]}}]}}],loc:{start:0,end:1094}};n.loc.source={body:"fragment AccommodationSegmentFragment on AccommodationSegment {
  type
  beginDate
  endDate
  meal {
    id
    title
  }
  content {
    title
    assets
    hotelRating
    facilities {
      id
      title
    }
    distances {
      beach
      cityCenter
    }
    categories {
      id
      title
    }
    photos {
      gallery
    }
    reviews {
      customersRating
      positiveReviewsPercentage
      reviewsNumber
      ratings {
        title
        value
      }
    }
    destinations {
      country {
        photos {
          gallery
        }
      }
      province {
        photos {
          gallery
        }
      }
    }
    geographicalIdentifiers {
      id
      title
      type
      parentId
      startingDestination
    }
    geolocation {
      lat
      lng
    }
    newContent {
      assets
      photos @include(if: $includeNewContentPhoto) {
        url
      }
      title @include(if: $includeNewContentTitle)
    }
    descriptions @include(if: $includeDescriptions) {
      id
      title
      text {
        withoutHtml
      }
    }
  }
